import math

def build_instance(rng):
    point_count = rng.randint(3, 10)
    answer = math.comb(point_count, 2)
    check = 0
    for i in range(point_count):
        for j in range(i + 1, point_count):
            check += 1
    assert answer == check, f'answer={answer} check={check}'
    parameters = {'point_count': point_count}
    return (parameters, answer, check)



